import './App.css';
import  AddTask from "./addtask/AddTask";
import  Task  from './gettask/Task';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';

function App() {
  const route = createBrowserRouter([
    {
      path: "/",
      element: <Task />,
    },
    {
      path: "/addtask",
      element: <AddTask />,
    },
  ]);

  return (
    <div className="App">
      <RouterProvider router={route} />
    </div>
  );
}

export default App;
